class Solution { fun maxValueAfterReverse(nums:IntArray):Int{val n=nums.size;var base=0;var gain=0;var maxOfMin=Int.MIN_VALUE;var minOfMax=Int.MAX_VALUE;for(i in 0 until n-1){val a=nums[i];val b=nums[i+1];val difference=kotlin.math.abs(a-b);base+=difference;gain=maxOf(gain,kotlin.math.abs(nums[0]-b)-difference,kotlin.math.abs(nums[n-1]-a)-difference);maxOfMin=maxOf(maxOfMin,minOf(a,b));minOfMax=minOf(minOfMax,maxOf(a,b))};if(n>1)gain=maxOf(gain,2*(maxOfMin-minOfMax));return base+gain} }
